input.content:
// Request/session-safe validated identity context.
//
// The validated identity is stored in a `tokio` task-local so that each
// in-flight request carries its own identity. This is concurrency-safe: two
// concurrent clients are processed in distinct tasks, so neither can observe
// the other's identity. This deliberately replaces the lab's global
// `CURRENT_CLAIMS` slot, which is only safe for sequential traffic.
//
// The auth middleware sets the value for the duration of the downstream
// request; the rmcp tool handlers read it at call time.

use crate::oauth::AuthStrength;

/// The validated identity for the current request.
#[derive(Clone, Debug)]
pub struct Identity {
    pub user_id: i64,
    pub client_id: String,
    pub scopes: Vec<String>,
    pub auth_strength: AuthStrength,
    pub auth_time: i64,
    pub token_id: String,
}

impl Identity {
    pub fn has_scope(&self, scope: &str) -> bool {
        self.scopes.iter().any(|s| s == scope)
    }
}

impl From<&crate::oauth::TokenValidationResult> for Identity {
    fn from(token: &crate::oauth::TokenValidationResult) -> Self {
        Self {
            user_id: token.user_id,
            client_id: token.oauth_client_id.clone(),
            scopes: token.scopes.clone(),
            auth_strength: token.auth_strength.clone(),
            auth_time: token.auth_time,
            token_id: token.token_id.clone(),
        }
    }
}

tokio::task_local! {
    /// The validated identity for the current request, if authenticated.
    pub static IDENTITY: Option<Identity>;
}

/// Read the validated identity for the current request.
///
/// Returns `None` when no identity has been established for this task (i.e. the
/// request did not pass the auth middleware). Tool handlers treat `None` as an
/// authorization failure and fail closed.
pub fn current() -> Option<Identity> {
    IDENTITY
        .try_with(|v| v.clone())
        .ok()
        .flatten()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn identity_from_token_validation_result() {
        let token = crate::oauth::TokenValidationResult {
            user_id: 42,
            oauth_client_id: "client-1".to_string(),
            scopes: vec!["commoncal.calendar.metadata.read".to_string()],
            auth_strength: AuthStrength::Passkey,
            auth_time: 1_700_000_000,
            token_id: "token-1".to_string(),
        };
        let identity = Identity::from(&token);
        assert_eq!(identity.user_id, 42);
        assert_eq!(identity.client_id, "client-1");
        assert!(identity.has_scope("commoncal.calendar.metadata.read"));
        assert!(!identity.has_scope("commoncal.event.create"));
        assert_eq!(identity.auth_time, 1_700_000_000);
        assert_eq!(identity.token_id, "token-1");
    }

    #[tokio::test]
    async fn current_returns_none_outside_auth_scope() {
        assert!(current().is_none());
    }

    #[tokio::test]
    async fn current_returns_identity_within_auth_scope() {
        let identity = Identity {
            user_id: 7,
            client_id: "client-7".to_string(),
            scopes: vec![],
            auth_strength: AuthStrength::Mfa,
            auth_time: 0,
            token_id: "token-7".to_string(),
        };
        let observed = IDENTITY
            .with_value(Some(identity.clone()), async { current() })
            .await;
        assert_eq!(observed, Some(identity));
    }

    #[tokio::test]
    async fn concurrent_tasks_do_not_share_identity() {
        let alice = Identity {
            user_id: 1,
            client_id: "alice".to_string(),
            scopes: vec![],
            auth_strength: AuthStrength::Passkey,
            auth_time: 0,
            token_id: "a".to_string(),
        };
        let bob = Identity {
            user_id: 2,
            client_id: "bob".to_string(),
            scopes: vec![],
            auth_strength: AuthStrength::Passkey,
            auth_time: 0,
            token_id: "b".to_string(),
        };

        let alice_task = tokio::spawn(async move {
            IDENTITY
                .with_value(Some(alice.clone()), async {
                    // Yield to force interleaving with the other task.
                    tokio::task::yield_now().await;
                    current().map(|i| i.user_id)
                })
                .await
        });
        let bob_task = tokio::spawn(async move {
            IDENTITY
                .with_value(Some(bob.clone()), async {
                    tokio::task::yield_now().await;
                    current().map(|i| i.user_id)
                })
                .await
        });

        let (alice_user, bob_user) = tokio::join!(alice_task, bob_task);
        assert_eq!(alice_user.unwrap().unwrap(), 1, "alice must see her own identity");
        assert_eq!(bob_user.unwrap().unwrap(), 2, "bob must see his own identity");
    }
}

// Bearer-token authentication for the complete MCP service.
//
// This middleware wraps the entire rmcp Streamable HTTP service so that the
// first unauthenticated `initialize` receives a standards-compliant 401
// challenge (RFC 6750 `WWW-Authenticate`) whose `resource_metadata` parameter
// is the public protected-resource metadata URL derived from
// `MCP_PUBLIC_RESOURCE_URL`. No loopback or lab URL is ever emitted.
//
// On success the validated identity is published to the request's task-local
// (see `crate::identity`) for the duration of the downstream request, so the
// rmcp tool handlers can authorize against it.

use axum::http::{HeaderMap, Request, StatusCode, header};
use axum::middleware::Next;
use axum::response::{IntoResponse, Response};
use serde_json::json;

use crate::identity::{Identity, IDENTITY};
use crate::oauth::{self, TokenError};

/// Configuration for the auth middleware.
#[derive(Clone)]
pub struct AuthState {
    pub issuer: String,
    pub resource: String,
    /// The public protected-resource metadata URL, e.g.
    /// `https://mcal.example.com/.well-known/oauth-protected-resource`.
    pub resource_metadata: String,
}

impl AuthState {
    /// Derive the public protected-resource metadata URL from the configured
    /// MCP resource URL. The metadata lives at the MCP origin under
    /// `/.well-known/oauth-protected-resource`.
    pub fn resource_metadata_url(resource_url: &str) -> String {
        let base = resource_url.trim_end_matches('/');
        // Strip the trailing `/mcp` path segment if present so the metadata is
        // anchored at the MCP origin, not nested under the endpoint path.
        let origin = base
            .strip_suffix("/mcp")
            .unwrap_or(base)
            .trim_end_matches('/');
        format!("{origin}/.well-known/oauth-protected-resource")
    }

    pub fn new(issuer: String, resource: String) -> Self {
        Self {
            resource_metadata: Self::resource_metadata_url(&resource),
            issuer,
            resource,
        }
    }
}

/// Extract the bearer token from the `Authorization` header.
fn extract_bearer_token(headers: &HeaderMap) -> Option<String> {
    let auth = headers.get(header::AUTHORIZATION)?.to_str().ok()?;
    let token = auth.strip_prefix("Bearer ")?;
    let token = token.trim();
    if token.is_empty() {
        return None;
    }
    Some(token.to_string())
}

/// Sanitize a string for use in a `WWW-Authenticate` header value.
fn sanitize(s: &str) -> String {
    s.chars()
        .take(120)
        .map(|c| match c {
            '"' | '\\' => '-',
            c if (c as u32) < 0x20 => '-',
            c => c,
        })
        .collect()
}

/// Build a standards-compliant 401 challenge referencing the public
/// protected-resource metadata URL.
fn unauthorized(state: &AuthState, error: &str, description: &str) -> Response {
    let challenge = format!(
        "Bearer realm=\"mcp\", resource_metadata=\"{}\", error=\"{}\"",
        state.resource_metadata,
        sanitize(error)
    );
    let body = json!({
        "error": error,
        "error_description": description,
    });
    Response::builder()
        .status(StatusCode::UNAUTHORIZED)
        .header(header::WWW_AUTHENTICATE, challenge)
        .header(header::CONTENT_TYPE, "application/json")
        .body(axum::body::Body::from(body.to_string()))
        .unwrap_or_else(|_| Response::new(axum::body::Body::empty()))
}

/// Map a token validation error to an OAuth `error` code and description.
fn token_error_params(e: &TokenError) -> (&'static str, String) {
    match e {
        TokenError::MissingToken => ("invalid_request", "authorization token is required".to_string()),
        TokenError::Expired => ("invalid_token", "access token has expired".to_string()),
        TokenError::InvalidAudience => (
            "invalid_target",
            "token audience does not match this resource".to_string(),
        ),
        TokenError::InvalidIssuer => (
            "invalid_token",
            "token issuer is not trusted".to_string(),
        ),
        TokenError::Revoked => ("invalid_token", "token has been revoked".to_string()),
        _ => ("invalid_token", "invalid authorization token".to_string()),
    }
}

/// The auth middleware. Validates the bearer token and publishes the identity
/// to the request's task-local for the downstream rmcp service.
pub async fn auth_middleware(
    axum::extract::State(state): axum::extract::State<AuthState>,
    headers: HeaderMap,
    request: Request<axum::body::Body>,
    next: Next,
) -> Response {
    let token = match extract_bearer_token(&headers) {
        Some(t) => t,
        None => {
            return unauthorized(
                &state,
                "invalid_request",
                "missing or malformed bearer token",
            )
        }
    };

    match oauth::validate_access_token(&token, &state.issuer, &state.resource).await {
        Ok(result) => {
            let identity = Identity::from(&result);
            tracing::debug!(
                user_id = identity.user_id,
                client_id = %identity.client_id,
                "mcp request authorized"
            );
            IDENTITY
                .with_value(Some(identity), async move { next.run(request).await })
                .await
                .into_response()
        }
        Err(e) => {
            tracing::warn!(error = %e, "mcp token validation failed");
            let (code, description) = token_error_params(&e);
            unauthorized(&state, code, &description)
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn resource_metadata_url_derived_from_mcp_resource() {
        assert_eq!(
            AuthState::resource_metadata_url("https://mcal.example.com/mcp"),
            "https://mcal.example.com/.well-known/oauth-protected-resource"
        );
    }

    #[test]
    fn resource_metadata_url_handles_trailing_slash() {
        assert_eq!(
            AuthState::resource_metadata_url("https://mcal.example.com/mcp/"),
            "https://mcal.example.com/.well-known/oauth-protected-resource"
        );
    }

    #[test]
    fn resource_metadata_url_handles_nested_path() {
        assert_eq!(
            AuthState::resource_metadata_url("https://mcal.example.com/api/mcp"),
            "https://mcal.example.com/api/.well-known/oauth-protected-resource"
        );
    }

    #[test]
    fn auth_state_new_populates_metadata() {
        let state = AuthState::new(
            "https://auth.example.com".to_string(),
            "https://mcal.example.com/mcp".to_string(),
        );
        assert_eq!(
            state.resource_metadata,
            "https://mcal.example.com/.well-known/oauth-protected-resource"
        );
        assert_eq!(state.issuer, "https://auth.example.com");
        assert_eq!(state.resource, "https://mcal.example.com/mcp");
    }

    #[test]
    fn challenge_uses_public_metadata_and_bearer_scheme() {
        let state = AuthState::new(
            "https://auth.example.com".to_string(),
            "https://mcal.example.com/mcp".to_string(),
        );
        let resp = unauthorized(&state, "invalid_token", "bad token");
        assert_eq!(resp.status(), StatusCode::UNAUTHORIZED);
        let www = resp
            .headers()
            .get(header::WWW_AUTHENTICATE)
            .unwrap()
            .to_str()
            .unwrap()
            .to_string();
        assert!(www.starts_with("Bearer "));
        assert!(www.contains("resource_metadata=\"https://mcal.example.com/.well-known/oauth-protected-resource\""));
        assert!(!www.contains("127.0.0.1"), "challenge must not leak a loopback URL");
    }

    #[test]
    fn extract_bearer_token_parses_valid_header() {
        let mut headers = HeaderMap::new();
        headers.insert(header::AUTHORIZATION, "Bearer abc123".parse().unwrap());
        assert_eq!(extract_bearer_token(&headers), Some("abc123".to_string()));
    }

    #[test]
    fn extract_bearer_token_rejects_missing_header() {
        assert_eq!(extract_bearer_token(&HeaderMap::new()), None);
    }

    #[test]
    fn extract_bearer_token_rejects_wrong_scheme() {
        let mut headers = HeaderMap::new();
        headers.insert(header::AUTHORIZATION, "Basic abc123".parse().unwrap());
        assert_eq!(extract_bearer_token(&headers), None);
    }

    #[test]
    fn extract_bearer_token_rejects_empty_token() {
        let mut headers = HeaderMap::new();
        headers.insert(header::AUTHORIZATION, "Bearer ".parse().unwrap());
        assert_eq!(extract_bearer_token(&headers), None);
    }

    #[test]
    fn token_error_params_maps_expired() {
        let (code, desc) = token_error_params(&TokenError::Expired);
        assert_eq!(code, "invalid_token");
        assert!(desc.contains("expired"));
    }

    #[test]
    fn token_error_params_maps_missing() {
        let (code, _) = token_error_params(&TokenError::MissingToken);
        assert_eq!(code, "invalid_request");
    }
}

// calendar_list tool handler.
//
// Returns the user's calendars filtered by McpGrant permissions.
// Requires:
// - Valid OAuth token
// - McpGrant with calendar metadata read permission
// - Calendar IDs in grant's allowed_calendar_ids
//
// The domain logic returns a JSON value; the rmcp service layer wraps it in an
// MCP content block. HTTP transport concerns live in the service layer, not
// here.

use serde::Deserialize;

use crate::error::ToolError;
use crate::mcp_grant::check_calendar_access;
use crate::output_schema::{CalendarListOutput, CalendarSummary};
use crate::tools::AuthorizedToolContext;

#[derive(Debug, Deserialize)]
pub struct CalendarListParams {
    #[serde(default)]
    pub include_access: bool,
}

/// Handle the calendar_list tool call.
///
/// Authorization pipeline:
/// 1. Auth middleware validates the OAuth token and publishes the identity.
/// 2. Service layer resolves the authoritative grant.
/// 3. Check the grant's calendar-list permission.
/// 4. Call CommonCal core to list calendars.
/// 5. Filter by the grant's allowed_calendar_ids.
/// 6. Return the structured result.
pub async fn handle(
    context: &AuthorizedToolContext<'_>,
    _params: CalendarListParams,
) -> Result<serde_json::Value, ToolError> {
    let grant = context.grant;

    // Check tool permission against the authoritative grant.
    //
    // calendar_list is a calendar-metadata read; it is gated by the
    // availability/metadata capability, NOT by the availability_find tool
    // capability. (Previously this checked the wrong capability.)
    if !crate::mcp_grant::check_tool_permission(grant, "calendar_list") {
        return Err(ToolError::Forbidden(
            "calendar_list requires calendar metadata read permission".to_string(),
        ));
    }

    // Fetch calendars from CommonCal core.
    let calendars = context
        .internal_client
        .list_calendars(context.token.user_id)
        .await
        .map_err(|e| ToolError::Internal(format!("calendar fetch failed: {}", e)))?;

    // Filter by the grant's allowed calendars.
    let filtered: Vec<CalendarSummary> = calendars
        .into_iter()
        .filter(|c| check_calendar_access(grant, c.id))
        .map(|c| CalendarSummary {
            id: c.id,
            name: c.name,
            color: String::new(),
            access: c.access,
        })
        .collect();

    Ok(serde_json::to_value(CalendarListOutput {
        calendars: filtered,
    })
    .unwrap_or_else(|_| serde_json::json!({ "calendars": [] })))
}

