/// Build the authorized context for a tool call from the identity and grant.
///
/// The `TokenValidationResult` is created here and must outlive the tool
/// handler call. Callers must keep the returned context alive for the duration
/// of the call.
fn build_context<'a>(
    internal_client: &'a InternalClient,
    identity: &'a identity::Identity,
    grant: &'a McpGrant,
) -> (TokenValidationResult, AuthorizedToolContext<'a>) {
    let token = TokenValidationResult {
        user_id: identity.user_id,
        oauth_client_id: identity.client_id.clone(),
        scopes: identity.scopes.clone(),
        auth_strength: identity.auth_strength.clone(),
        auth_time: identity.auth_time,
        token_id: identity.token_id.clone(),
        expires_at: i64::MAX,
    };
    let context = AuthorizedToolContext {
        token: &token,
        grant,
        internal_client,
    };
    (token, context)
}

